def load_registry(path):
    kinds = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip("\n")
            m = re.match(r'^(concept|edge|theme|tissue|supertheme|superedge):\s*([^\|]+?)\s*\|', line)
            if m:
                kind, id_ = m.group(1), m.group(2).strip()
                kinds.setdefault(kind, set()).add(id_)
    return kinds

REGISTRY = load_registry(REG_PATH)

def leaf(id_, name, kind, ref_id, narrative, children=None):
    return {
        "id": id_, "name": name,
        "ref": {"kind": kind, "id": ref_id},
        "narrative": narrative,
        "children": children if children is not None else []
    }

def chapter(id_, name, narrative, children):
    return {"id": id_, "name": name, "narrative": narrative, "ref": None, "children": children}

def root(id_, tab, claim, name, narrative, intro, children):
    return {"id": id_, "tab": tab, "claim": claim, "name": name,
            "narrative": narrative, "intro": intro, "ref": None, "children": children}

