# ============================================================
DATA = {"paperStories": [{"id": "persona-vectors", "stories": [pv_inside, pv_across, pv_bigpicture]}]}

with open(OUT_PATH, "w", encoding="utf-8") as f:
    json.dump(DATA, f, ensure_ascii=False, indent=1)

print("WROTE", OUT_PATH)

# ============================================================
# VALIDATION
# ============================================================

def walk(node, out):
    out.append(node)
    for c in node.get("children", []):
        walk(c, out)

all_ids = []
errors = []

def word_count(s):
    return len(re.findall(r"\S+", s))

for story in DATA["paperStories"][0]["stories"]:
    nodes = []
    walk(story, nodes)
    for n in nodes:
        all_ids.append(n["id"])

# uniqueness
seen = set()
dupes = set()
for i in all_ids:
    if i in seen:
        dupes.add(i)
    seen.add(i)
if dupes:
    errors.append(f"DUPLICATE ids: {dupes}")
else:
    print(f"OK: {len(all_ids)} node ids, all unique")

# refs resolve
ref_count_by_story = {}
for story in DATA["paperStories"][0]["stories"]:
    sid = story["id"]
    nodes = []
    walk(story, nodes)
    kind_counts = {}
    theme_tissue_used = {}
    for n in nodes:
        ref = n.get("ref")
        if ref:
            kind, rid = ref["kind"], ref["id"]
            kind_counts[kind] = kind_counts.get(kind, 0) + 1
            if kind not in REGISTRY or rid not in REGISTRY[kind]:
                errors.append(f"[{sid}] BAD REF kind={kind} id={rid} (node {n['id']})")
            if kind in ("theme", "tissue", "supertheme"):
                theme_tissue_used.setdefault(rid, []).append(n["id"])
    for rid, nodelist in theme_tissue_used.items():
        if len(nodelist) > 1:
            errors.append(f"[{sid}] theme/tissue/supertheme {rid} reffed more than once: {nodelist}")
    ref_count_by_story[sid] = kind_counts

print("\nRef counts by kind, per story:")
for sid, kc in ref_count_by_story.items():
    print(f"  {sid}: {kc}  total={sum(kc.values())}")

# word count check on narratives (60-160) - report outliers, not necessarily hard error for chapters/roots
print("\nWord-count outliers (leaf narratives outside 60-160):")
for story in DATA["paperStories"][0]["stories"]:
    nodes = []
    walk(story, nodes)
    for n in nodes:
        if n.get("ref") is not None:  # leaf
            wc = word_count(n["narrative"])
            if wc < 60 or wc > 160:
                print(f"  {story['id']} :: {n['id']} = {wc} words")

# intro checks
print("\nIntro checks:")
for story in DATA["paperStories"][0]["stories"]:
    intro = story["intro"]
    paras = intro.split("\n\n")
    wc = word_count(intro)
    print(f"  {story['id']}: {len(paras)} paragraphs, {wc} words total")
    if len(paras) != 2:
        errors.append(f"[{story['id']}] intro does not have exactly 2 paragraphs")
    if wc < 35 or wc > 160:
        errors.append(f"[{story['id']}] intro word count {wc} out of 35-160")
    if "[[" in intro or "(persona" in intro:
        errors.append(f"[{story['id']}] intro contains wiki-link or citation")

# big-picture check: exactly 5 chapters, concept-only leaf refs
bp = DATA["paperStories"][0]["stories"][2]
if len(bp["children"]) != 5:
    errors.append(f"big-picture has {len(bp['children'])} chapters, expected 5")
bp_nodes = []
walk(bp, bp_nodes)
bp_concept_refs = 0
for n in bp_nodes:
    ref = n.get("ref")
    if ref:
        if ref["kind"] != "concept":
            errors.append(f"[big-picture] leaf {n['id']} has non-concept ref kind {ref['kind']}")
        else:
            bp_concept_refs += 1
print(f"\nBig-picture concept ref count: {bp_concept_refs}")

# JSON parse check (round trip)
with open(OUT_PATH, encoding="utf-8") as f:
    reparsed = json.load(f)
print("\nJSON reparse OK")

if errors:
    print("\n=== ERRORS ===")
    for e in errors:
        print(" -", e)
    sys.exit(1)
else:
    print("\nALL VALIDATION CHECKS PASSED")
